INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/46f543ceeb3df4fc512bb882ee567e6a76892890/content/books/zizhi-tongjian/vol-293/year-0956/part-07/sources/library/jiuwudaishi-116-december-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002763；EPUB电子本，纸本及异文待核", "id": "765c0db4-b21b-5094-98fd-2c5131eca4b4"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/46f543ceeb3df4fc512bb882ee567e6a76892890/content/books/zizhi-tongjian/vol-293/year-0956/part-07/sources/library/jiuwudaishi-116-november-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002762；EPUB电子本，纸本及异文待核", "id": "73ce811f-5286-5ac7-8597-39d336b527a9"}, {"title": "宋史·巻四百五十七", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/46f543ceeb3df4fc512bb882ee567e6a76892890/content/books/zizhi-tongjian/vol-293/year-0956/part-07/sources/library/songshi-457-chentuan-956/source.txt", "note": "《宋史》巻四百五十七，段落 songshi-9c6e46fee832-p073303；EPUB电子本，纸本及异文待核", "id": "5f043f3f-ad30-5cec-9dea-e3d91fb53543"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/46f543ceeb3df4fc512bb882ee567e6a76892890/content/books/zizhi-tongjian/vol-293/year-0956/part-07/sources/library/tongjian-293-956-year-end/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003480；电子底本待考，分段待核", "id": "5e5f3333-c0c8-5644-977c-487cfa039e75"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ea70f60f767f3688984c5ec3aa3a578a6a95317a/content/books/zizhi-tongjian/vol-293/year-0956/part-05/sources/library/tongjian-293-956-hunan-yangzhou-withdrawal/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003479；电子底本待考，分段待核", "id": "c976d062-2cad-52b8-b653-331b40f65e06"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d1355da27db0b773c786b11815d5b346a3806769/content/books/zizhi-tongjian/vol-293/year-0956/part-06/sources/library/jiuwudaishi-116-october-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002761；EPUB电子本，纸本及异文待核", "id": "d6f77a98-15c3-58b0-9b42-f35ee3e47e8d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "赵普", "aliases": ["趙普"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟人，字则平。早年为刘词幕僚，获刘词遗表推荐；956年滁州攻取后，范质荐任军事判官。赵匡胤与其交谈后赏识他。面对百余名被捕者拟处死，赵普请求先审讯，再决定处罚，使多数人保全性命。", "biography": null, "status": "draft", "id": "639a1338-0a6d-5de9-8169-f35cbc62dcd9"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "曹翰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名人，曾为郡中小吏，受郭威知遇后随柴荣，任澶州牙将。郭威病中，劝柴荣入宫侍疾，《宋史》还记柴荣让他总理府务。生卒年暂未核定。", "biography": null, "status": "draft", "id": "9c79672a-4f9e-5a5f-8dfb-9360586d8ee8"}, {"name": "陈抟", "aliases": ["陳摶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真源人，华山隐士。956年应柴荣召见，劝皇帝以治理天下为务，不必求飞升与炼金术，获准还山。《宋史》另记其辞谢谏议大夫任命。生卒年本段未载。", "biography": null, "status": "draft", "id": "045a7552-bd8b-5292-b509-7de1e0f8a077"}, {"name": "陈处尧", "aliases": ["陳處堯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐兵部郎中。956年李璟派其携厚礼渡海向契丹求援，契丹没有出兵，并将他留住。他后来多次当面指责契丹君主而未受处罚，具体日期未载。", "biography": null, "status": "draft", "id": "1209f341-ea4a-5e9d-b4d8-6574a2cef125"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "赵季文", "aliases": ["趙季文"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀弓箭库使。956年平定陵、荣二州史书称为獠的群体叛乱。具体战斗日期、个人籍贯与生卒年未载。", "biography": null, "status": "draft", "id": "1957bdeb-e31c-505b-881c-65046d1f9c97"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "钱弘亿", "aliases": ["錢弘億"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "11129a7d-ca77-5d63-b3fd-b341fb184b7e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣任赵匡胤为定国节度使、殿前都指挥使", "start_year": 956, "end_year": 956, "time_original": "956年十月甲申", "dynasty": "五代十国", "description": "柴荣任赵匡胤为定国节度使、殿前都指挥使。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a15b8911-7fa2-5827-aef4-9e54bd97a032"}, {"title": "赵匡胤推荐赵普为节度推官", "start_year": 956, "end_year": 956, "time_original": "956年十月赵匡胤获任定国节度使条所记，推荐日未独载", "dynasty": "五代十国", "description": "赵匡胤推荐赵普为节度推官。", "phases": [], "location_name": "渭州至节度幕府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "964d1bdb-d0d4-59a7-bbbe-8659b584f10c"}, {"title": "张永德密报李重进有二心，柴荣不信", "start_year": 956, "end_year": 956, "time_original": "956年十月条之后、十一月条之前，具体日未载", "dynasty": "五代十国", "description": "张永德与李重进不和，秘密上表说李重进有二心，柴荣没有相信。指控本身有记载，但不能因此把李重进记为已证实谋反。", "phases": [], "location_name": "后周军营及朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dfe8d7ae-d545-538c-9e27-45a6f73ae657"}, {"title": "李重进单骑到张永德营中宴谈，化解猜疑", "start_year": 956, "end_year": 956, "time_original": "956年两将猜疑之后，具体日未载", "dynasty": "五代十国", "description": "两将各拥重兵，史书称众人担忧。李重进单骑来到张永德营中，从容宴饮，指出两人都是皇室至亲，不应互疑，张永德因此释疑，众心也安。肺腑指皇室亲近关系，不据这句话新建两人血缘或结义关系。", "phases": [], "location_name": "张永德军营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e2856163-40b9-55aa-b24c-58933429588e"}, {"title": "李璟以蜡书诱李重进，李重进将书呈报柴荣", "start_year": 956, "end_year": 956, "time_original": "956年两将关系缓和之后、孙晟被杀之前，具体日未载", "dynasty": "五代十国", "description": "李璟得知两将情况，以蜡书许厚利诱李重进，书中有谤毁与反间言辞。李重进将书上奏，不能把收信等同接受诱约或已与南唐结盟。", "phases": [], "location_name": "南唐至后周军营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "349ed6f6-c069-55e1-8877-6ddd1f2a83c0"}, {"title": "柴荣厚待留在大梁的孙晟、钟谟，询问南唐情况", "start_year": null, "end_year": null, "time_original": "956年十一月杀孙晟之前的接待过程，各次召见年月未载", "dynasty": "五代十国", "description": "柴荣厚待留在大梁的孙晟、钟谟，询问南唐情况。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "588e1fa7-8928-5277-9538-2b8928afa63d"}, {"title": "柴荣因南唐蜡书责问孙晟，孙晟拒说军政虚实", "start_year": 956, "end_year": 956, "time_original": "956年十一月乙巳处刑以前，具体责问日未载", "dynasty": "五代十国", "description": "柴荣因南唐蜡书责问孙晟，孙晟拒说军政虚实。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ea495db8-7503-5fa2-a013-b4fe177e9e56"}, {"title": "柴荣命曹翰再问孙晟，孙晟拒答后被处死", "start_year": 956, "end_year": 956, "time_original": "956年十一月乙巳", "dynasty": "五代十国", "description": "柴荣命曹翰再问孙晟，孙晟拒答后被处死。", "phases": [], "location_name": "大梁右军巡院", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "08774bc9-cb4f-5d45-aa78-0565f92762ec"}, {"title": "孙晟的百余名随从也被杀", "start_year": 956, "end_year": 956, "time_original": "956年十一月孙晟被杀时", "dynasty": "五代十国", "description": "孙晟的百余名随从也被杀。", "phases": [], "location_name": "后周，随从处刑具体场所未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3addfed1-597c-5728-8cbe-28999b24515d"}, {"title": "钟谟被贬为耀州司马", "start_year": 956, "end_year": 956, "time_original": "956年十一月孙晟被杀条所记", "dynasty": "五代十国", "description": "钟谟被贬为耀州司马。", "phases": [], "location_name": "耀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bf01e3ec-3578-59dd-a32c-a42f4f2b280d"}, {"title": "柴荣后悔杀孙晟，召钟谟并任卫尉少卿", "start_year": null, "end_year": null, "time_original": "956年十一月杀孙晟之后，具体召回授官年日未载", "dynasty": "五代十国", "description": "柴荣后悔杀孙晟，召钟谟并任卫尉少卿。", "phases": [], "location_name": "耀州至后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f84c2e18-4d5e-5709-9c99-a4898b8cecbc"}, {"title": "陈抟劝柴荣治理天下，不要求飞升与炼金术", "start_year": 956, "end_year": 956, "time_original": "956年十一月戊申遣还以前，具体召见日未载", "dynasty": "五代十国", "description": "陈抟劝柴荣治理天下，不要求飞升与炼金术。", "phases": [], "location_name": "华山至后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "55872bef-ec61-5e7f-ad18-a4e46f057521"}, {"title": "陈抟拒绝柴荣所授谏议大夫", "start_year": 956, "end_year": 956, "time_original": "《宋史》显德三年（956年）召见期间，具体日未载", "dynasty": "五代十国", "description": "陈抟拒绝柴荣所授谏议大夫。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e570b946-4f25-5ba7-a558-a41bd2dec0cb"}, {"title": "柴荣放陈抟还山，命地方长官经常问候", "start_year": 956, "end_year": 956, "time_original": "956年十一月戊申", "dynasty": "五代十国", "description": "柴荣放陈抟还山，命地方长官经常问候。", "phases": [], "location_name":